insert into ve_video_tours (slug,title,kind,page_url,narrator,voice_id,script_doc,status) values ('welcome-guide','The Welcome Guide','guide','/passport','liz','IUMUPi350HfIhyzUBJB3','docs/proposals/explorer-welcome-guide.md','lookbook') on conflict (slug) do nothing;
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,1,'Welcome','Hi, I''m Liz. Maybe you want to eat out without guessing, find your people, or do more for the animals than you are right now. Wherever you''re starting from, this Guide is how you get there. You''ll start out just looking around, and you''ll finish knowing your city, your community, and exactly where you fit in. Let''s go.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-1-v1.mp3',1,true,19.9 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=1);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,2,'Why listen to us','Why listen to us? We''ve spent more than ten years inside this community: activism, events, content, running businesses, and hundreds of long conversations about what people needed. Now we can finally build it, and we can''t get it right without you.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-2-v1.mp3',1,true,15.6 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=2);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,3,'Find your way','Search for anything and it shows up. The Directory has places to eat and shop, people, groups and nonprofits, city by city. Your city has its own Daily Pulse, its boards and its events. And our Guides each walk you through one topic.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-3-v1.mp3',1,true,17.3 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=3);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,4,'Take part','Vote for the places you love. Your favorites tell us who to spotlight next. Check in when you visit and take on bounties to earn points. Spend them to open Guides and ask your Guide anything, or give them to the places and causes you care about.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-4-v1.mp3',1,true,15.1 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=4);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,5,'Your path','Everyone starts as an Explorer. Run a restaurant, host events, make content or work with a nonprofit? Each one has its own path, its own Guide and its own badge.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-5-v1.mp3',1,true,9.8 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=5);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,6,'Make it better','This is the part that matters most. Use it in your day to day, and tell us what''s working, what isn''t, and what you wish you could do. Every page has a Feedback button. Ask your Guide, or ask a person on our team. Search for something we don''t have yet, and it goes to our team. We read all of it, and we build from it every day. We''re real people, supported by technology that finally lets us carry out a vision we''ve been working on since 2016.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-6-v1.mp3',1,true,30.1 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=6);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,7,'For the animals','Here''s where it''s all going. With a network of businesses, people and nonprofits that actually show up, we can run campaigns that move the needle for the animals, the reason we''re all here.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-7-v1.mp3',1,true,10.1 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=7);
insert into ve_video_chapters (tour_id,n,title,line,audio_url,audio_ver,stt_ok,seconds) select id,8,'Become a Founder','Right now you''re early, and that''s rare. If you feel you know enough, take the survey and get started right away. It''s a few quick questions, about two minutes, and you''re in, free, with 250 points to use across the platform. Want to take your time? Each section of this Guide breaks down exactly how to use it today. Either way, join before midnight on January first and you''re a Founding Member for good. Founders unlock some really cool things in 2027, and the only way to hear about them, and lock them in for yourself, is to join today.','https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/liz/welcome-guide/tour-8-v1.mp3',1,true,34.6 from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_chapters c join ve_video_tours t2 on t2.id=c.tour_id where t2.slug='welcome-guide' and c.n=8);
insert into ve_video_shots (tour_id,chapter_n,ord,kind,brief,image_url,audio_from,audio_to,status,readiness,flag,line) select id,1,1,'on_camera','Liz on camera: "Hi, I''m Liz." Lip-synced, about 1.3 s, held to 3 s with her mouth closed, from her Overview scene (the market, waving).','https://vegansexplore.com/public/guides/welcome/liz-overview.jpg',0,1.3,'proposed','ready',null,'Hi, I''m Liz.' from ve_video_tours where slug='welcome-guide' and not exists (select 1 from ve_video_shots s join ve_video_tours t2 on t2.id=s.tour_id where t2.slug='welcome-guide' and s.chapter_n=1 and s.ord=1);
